INSERT OR IGNORE INTO kitchen_activity(event_key,actor_name,kind,title,action,summary,created_at) VALUES('release-kitchen-popups-2026-10-23','Vanity Vair','website','A little more room in the Kitchen','Site update','Moved My profile, Trash, and Kitchen log to the bottom of the sidebar, in that order. Ads and Photo library tiles now open their editors with one click. Ad forms open in a popup, and photo popups show the image being edited. Unsaved changes are protected when closing.',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
